(function(){const t=document.createElement("template");t.innerHTML="<div id=\"bootStatus\" role=\"status\" style=\"padding:12px;background:#3c3224;color:#fff4d1;font:14px/1.5 system-ui\">ゲームを起動しています。プレビューでは操作できない場合があります。この表示が残る場合は、案内された試遊 URL から開いてください。</div>\n<noscript><p>この表示環境では JavaScript が無効です。ゲームを実行できるブラウザで HTML を開いてください。</p></noscript>\n\n\n<!-- Candidate UI shell only. Keep battle, wallet, room, and sprite logic in the existing controller. -->\n<main id=\"app\">\n  <section id=\"homeScreen\" class=\"screen home-screen\" aria-labelledby=\"homeTitle\">\n    <div id=\"homeAmbience\" class=\"home-ambience\" aria-hidden=\"true\" hidden>\n      <div class=\"home-ambience-plane\">\n        <i class=\"home-light home-light--near\"></i>\n        <i class=\"home-light home-light--middle\"></i>\n        <i class=\"home-light home-light--back\"></i>\n        <i class=\"home-light home-light--table\"></i>\n        <i class=\"home-light home-light--candle\"></i>\n        <i class=\"home-light home-light--mantel-left\"></i>\n        <i class=\"home-light home-light--mantel-right\"></i>\n        <i class=\"home-light home-light--hearth\"></i>\n      </div>\n    </div>\n    <h1 id=\"homeTitle\" class=\"home-title\"><img alt=\"どっちが勝つ？\" width=\"2172\" height=\"724\" src=\"https://gbaconrice.github.io/docchi-ga-katsu/releases/reconstructed-20261106/assets/87cad6a5de30c0e20eb795423fee38a46ee68f66aa0a4a8319f81019db0ad5e5.png\"></h1>\n    <button id=\"soloStart\" class=\"home-choice cta-primary\" type=\"button\">ひとりで遊ぶ</button>\n    <button id=\"showMultiplayer\" class=\"home-choice cta-secondary\" type=\"button\">みんなで遊ぶ</button>\n  </section>\n\n  <div id=\"menuAudioDock\" class=\"menu-audio-dock\" aria-label=\"サウンド設定\"></div>\n\n  <button id=\"mockRoom\" type=\"button\" hidden aria-hidden=\"true\" tabindex=\"-1\"></button>\n\n  <section id=\"roomScreen\" class=\"screen room-screen\" hidden aria-labelledby=\"roomTitle\">\n    <h2 id=\"roomTitle\">みんなで遊ぶ</h2>\n    <button id=\"createRoom\" class=\"cta cta-primary\" type=\"button\">部屋をつくる</button>\n    <button id=\"beginRound\" class=\"cta cta-primary\" type=\"button\" hidden>第1戦へ</button>\n    <label class=\"room-code-label\" for=\"roomId\">部屋コードで参加</label>\n    <div class=\"room-join-row\">\n      <input id=\"roomId\" type=\"text\" autocomplete=\"off\" maxlength=\"128\" placeholder=\"部屋コード\" />\n      <button id=\"joinRoom\" class=\"cta cta-secondary\" type=\"button\">参加</button>\n    </div>\n    <section id=\"publicRooms\" class=\"public-rooms\" aria-labelledby=\"publicRoomsTitle\">\n      <div class=\"public-rooms-heading\"><h3 id=\"publicRoomsTitle\">公開ルーム</h3><button id=\"refreshPublicRooms\" type=\"button\">更新</button></div>\n      <p id=\"publicRoomsStatus\" aria-live=\"polite\">取得中…</p>\n      <div id=\"publicRoomsList\" class=\"public-rooms-list\"></div>\n    </section>\n    <button id=\"backHome\" class=\"text-button\" type=\"button\">戻る</button>\n  </section>\n\n  <div id=\"multiStatusRow\" class=\"multi-status-row\" hidden>\n    <div class=\"multi-status-content\">\n      <p id=\"multiSummary\" class=\"multi-summary\"></p>\n      <p id=\"roomStatus\" class=\"status-line\" aria-live=\"polite\"></p>\n    </div>\n    <button id=\"exitRoom\" class=\"text-button\" type=\"button\" hidden>退出</button>\n  </div>\n\n  <section id=\"gameScreen\" class=\"screen game-screen\" hidden aria-label=\"ゲーム\">\n    <div id=\"gameTopline\" class=\"game-topline\">\n      <p id=\"fieldStatus\" class=\"field-status\" role=\"region\" tabindex=\"0\" aria-label=\"地図名と効果\" aria-describedby=\"headerScrollHelp\">地図未定</p>\n      <p id=\"status\" class=\"round-status\" aria-live=\"polite\">第1／10戦</p>\n      <div class=\"wallet-pill\" aria-label=\"所持ゴールド\">\n        <img class=\"wallet-coin\" src=\"https://gbaconrice.github.io/docchi-ga-katsu/releases/reconstructed-20261106/assets/9b5895311d431c529597230751b0d4a5a39dd9df9d53832a114c96a90ccc8880.png\" width=\"26\" height=\"26\" alt=\"\" aria-hidden=\"true\" decoding=\"async\">\n        <span class=\"wallet-caption\" aria-hidden=\"true\">所持金</span>\n        <strong id=\"balance\" role=\"region\" tabindex=\"0\" aria-label=\"所持ゴールド\" aria-describedby=\"headerScrollHelp\">100</strong>\n      </div>\n      <button id=\"soundToggle\" class=\"battle-icon-button sound-toggle\" type=\"button\" aria-label=\"音を切り替える\" title=\"音\"><svg class=\"sound-glyph\" data-audio-icon viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path class=\"speaker-shape\" d=\"M3 9v6h4l5 4V5L7 9H3Z\"/><path class=\"sound-wave\" d=\"M15 9a5 5 0 0 1 0 6M17 6a9 9 0 0 1 0 12\"/><path class=\"sound-mute\" d=\"m15 9 6 6m0-6-6 6\"/></svg></button>\n    </div>\n    <span id=\"headerScrollHelp\" class=\"sr-only\">長い地図名と所持ゴールドは左右にスクロールすると全文を確認できます。</span>\n    <h2 id=\"phaseTitle\" class=\"sr-only\"></h2>\n\n    <section id=\"comparison\" class=\"comparison\" aria-label=\"対戦予想\">\n      <section class=\"stake-card\" aria-labelledby=\"stakeTitle\">\n        <h3 id=\"stakeTitle\">BET</h3>\n        <div class=\"stake-options\" role=\"group\" aria-label=\"BET額\">\n          <button id=\"stake0\" class=\"stake-option\" type=\"button\" aria-pressed=\"true\">0 G</button>\n          <button id=\"stake10\" class=\"stake-option\" type=\"button\" aria-pressed=\"false\">10%</button>\n          <button id=\"stake25\" class=\"stake-option\" type=\"button\" aria-pressed=\"false\">25 G</button>\n          <button id=\"stake50\" class=\"stake-option\" type=\"button\" aria-pressed=\"false\">50 G</button>\n          <button id=\"stake75\" class=\"stake-option\" type=\"button\" aria-pressed=\"false\">75%</button>\n          <button id=\"stake90\" class=\"stake-option\" type=\"button\" aria-pressed=\"false\">90%</button>\n          <button id=\"stake100\" class=\"stake-option\" type=\"button\" aria-pressed=\"false\">全額</button>\n        </div>\n        <p id=\"stakeHint\" class=\"stake-hint\" aria-live=\"polite\">的中 +10 G · 外れ −10 G · 引分 ±0 G</p>\n      </section>\n      <div id=\"comparisonScroll\" class=\"comparison-scroll\">\n        <div class=\"army-grid\" role=\"group\" aria-label=\"勝つ方\">\n          <button id=\"red\" class=\"army-card army-red\" type=\"button\" aria-pressed=\"false\" aria-label=\"左の軍\" aria-describedby=\"redStats\">\n            <span class=\"army-title sr-only\" id=\"redTitle\">左</span>\n            <canvas id=\"armyPreviewRed\" class=\"army-preview\" width=\"280\" height=\"168\" aria-label=\"左チームのキャラ\"></canvas>\n            <span id=\"redList\" class=\"army-summary sr-only\" aria-live=\"off\"></span>\n            <span id=\"redPicks\" class=\"prediction-picks\" aria-label=\"選択中・確定した参加者\" hidden></span>\n            <span id=\"redStats\" class=\"unit-stats comparison-list\" role=\"list\" aria-live=\"off\"></span>\n          </button>\n          <button id=\"blue\" class=\"army-card army-blue\" type=\"button\" aria-pressed=\"false\" aria-label=\"右の軍\" aria-describedby=\"blueStats\">\n            <span class=\"army-title sr-only\" id=\"blueTitle\">右</span>\n            <canvas id=\"armyPreviewBlue\" class=\"army-preview\" width=\"280\" height=\"168\" aria-label=\"右チームのキャラ\"></canvas>\n            <span id=\"blueList\" class=\"army-summary sr-only\" aria-live=\"off\"></span>\n            <span id=\"bluePicks\" class=\"prediction-picks\" aria-label=\"選択中・確定した参加者\" hidden></span>\n            <span id=\"blueStats\" class=\"unit-stats comparison-list\" role=\"list\" aria-live=\"off\"></span>\n          </button>\n        </div>\n\n\n        <!-- Legacy selector hooks remain hidden; matchup stats/traits are already visible above. -->\n        <div class=\"compatibility-hooks\" hidden aria-hidden=\"true\">\n          <label for=\"unitKind\">キャラの特徴</label><select id=\"unitKind\"></select>\n          <p id=\"unitTrait\"></p>\n        </div>\n      </div>\n      <div id=\"predictionFooter\" class=\"prediction-footer\"><div id=\"assetNoticeChoose\" hidden role=\"status\" style=\"font-size:12px;line-height:1.35;color:#3c2817;background:#f4e2b9;padding:4px 6px\"><span id=\"assetTextChoose\"></span> <button id=\"assetRetryChoose\" type=\"button\" hidden>再試行</button> <button id=\"assetContinueChoose\" type=\"button\" hidden>代替表示で続ける</button></div>\n        <button id=\"confirm\" class=\"cta cta-primary prediction-start\" type=\"button\" disabled>対戦開始</button>\n      </div>\n    </section>\n\n    <section id=\"battle\" class=\"battle\" hidden aria-label=\"戦闘\">\n      <div class=\"battle-toolbar\"><div id=\"assetNoticeBattle\" hidden role=\"status\" style=\"font-size:12px;line-height:1.35;color:#3c2817;background:#f4e2b9;padding:4px 6px\"><span id=\"assetTextBattle\"></span> <button id=\"assetRetryBattle\" type=\"button\" hidden>再試行</button> <button id=\"assetContinueBattle\" type=\"button\" hidden>代替表示で続ける</button></div>\n        <span id=\"battleChoice\" class=\"battle-choice\" hidden></span>\n        <p id=\"battleClock\" class=\"battle-clock\" aria-live=\"off\"></p>\n        <button id=\"unitsToggle\" class=\"battle-icon-button units-toggle\" type=\"button\" aria-label=\"キャラ一覧\" title=\"キャラ一覧\" aria-haspopup=\"dialog\" aria-controls=\"unitsPanel\"><span class=\"icon-slot icon-units\" data-icon-slot=\"units\" aria-hidden=\"true\"></span></button>\n        <button id=\"reactionToggle\" class=\"battle-icon-button reaction-toggle\" type=\"button\" aria-label=\"リアクション\" title=\"リアクション\" aria-controls=\"reaction-bar\" aria-expanded=\"false\" hidden><span class=\"reaction-toggle-emoji\" aria-hidden=\"true\">😄</span></button>\n        <button id=\"pause\" class=\"battle-icon-button control-button pause-toggle\" type=\"button\" aria-label=\"一時停止\" aria-haspopup=\"dialog\" aria-controls=\"pausePanel\" hidden>⏸</button>\n        <div id=\"reaction-bar\" class=\"reaction-bar\" role=\"group\" aria-label=\"リアクション\" hidden>\n          <button id=\"reactionCheer\" type=\"button\" aria-label=\"喜び\"><span class=\"reaction-emoji\" data-stamp-slot=\"cheer\" aria-hidden=\"true\">😄</span></button>\n          <button id=\"reactionWow\" type=\"button\" aria-label=\"驚き\"><span class=\"reaction-emoji\" data-stamp-slot=\"wow\" aria-hidden=\"true\">😮</span></button>\n          <button id=\"reactionFrustrated\" type=\"button\" aria-label=\"残念\"><span class=\"reaction-emoji\" data-stamp-slot=\"frustrated\" aria-hidden=\"true\">😭</span></button>\n          <button id=\"reactionApplause\" type=\"button\" aria-label=\"応援\"><span class=\"reaction-emoji\" data-stamp-slot=\"applause\" aria-hidden=\"true\">👏</span></button>\n        </div>\n      </div>\n        <div id=\"participantRailWrap\" class=\"participant-rail-wrap\" hidden>\n          <div id=\"participantRail\" class=\"participant-rail\" tabindex=\"0\" role=\"list\" aria-label=\"参加者。横にスクロールできます\"></div>\n          <span id=\"reactionOutside\" class=\"reaction-outside\" aria-live=\"polite\" hidden></span>\n        </div>\n      <div id=\"fieldStage\" class=\"field-stage\">\n      <div id=\"fieldMap\" class=\"field-map\">\n        <canvas id=\"field\" width=\"480\" height=\"538\" aria-label=\"左と右の軍の戦闘\"></canvas>\n        <div id=\"reaction-feedback\" class=\"reaction-feedback\" aria-live=\"polite\" aria-atomic=\"true\"></div>\n      </div>\n      <span id=\"openingCue\" class=\"opening-cue\" aria-hidden=\"true\" hidden>対戦開始</span>\n      <span id=\"combatSpectacle\" class=\"combat-spectacle\" aria-hidden=\"true\" hidden>\n        <i id=\"combatSpectacleRing\" class=\"combat-spectacle-ring\"></i>\n        <i id=\"combatSpectacleRays\" class=\"combat-spectacle-rays\"></i>\n        <i id=\"combatSpectacleCore\" class=\"combat-spectacle-core\"></i>\n      </span>\n      <span id=\"finalImpact\" class=\"combat-spectacle final-impact\" aria-hidden=\"true\" hidden>\n        <i id=\"finalImpactRing\" class=\"combat-spectacle-ring\"></i>\n        <i id=\"finalImpactRays\" class=\"combat-spectacle-rays\"></i>\n        <i id=\"finalImpactCore\" class=\"combat-spectacle-core\"></i>\n      </span>\n      </div>\n      <section id=\"crowdInspector\" class=\"crowd-inspector\" aria-label=\"選択したキャラ\" hidden>\n        <div class=\"crowd-inspector-copy\">\n          <span id=\"crowdFocusName\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">タップで詳細確認</span>\n          <span id=\"crowdFocusHP\" aria-live=\"off\"></span>\n        </div>\n        <button id=\"crowdPrevious\" type=\"button\" aria-label=\"前のキャラを選ぶ\" title=\"前のキャラ\">‹</button>\n        <button id=\"crowdNext\" type=\"button\" aria-label=\"次のキャラを選ぶ\" title=\"次のキャラ\">›</button>\n        <button id=\"crowdClear\" type=\"button\" aria-label=\"キャラの選択を解除\" title=\"選択を解除\" disabled>×</button>\n      </section>\n      \n      <button id=\"battleLog\" class=\"battle-log\" type=\"button\" hidden aria-live=\"off\" aria-expanded=\"false\" aria-controls=\"battleLogHistory\" aria-label=\"戦闘ログ。タップで履歴を開く\">\n        <span id=\"battleLogSource\" class=\"battle-log-name\"></span><span id=\"battleLogArrow\" aria-hidden=\"true\"></span><span id=\"battleLogTarget\" class=\"battle-log-name\"></span><span id=\"battleLogAction\" class=\"battle-log-action\">履歴 ▾</span>\n      </button>\n      <section id=\"battleLogHistory\" class=\"battle-log-history\" hidden aria-labelledby=\"battleLogHistoryTitle\">\n        <div class=\"battle-log-history-heading\"><strong id=\"battleLogHistoryTitle\">戦闘ログ</strong><button id=\"battleLogClose\" type=\"button\" aria-label=\"戦闘ログを閉じる\">閉じる</button></div>\n        <p id=\"battleLogStatus\"></p>\n        <ol id=\"battleLogHistoryList\" class=\"battle-log-history-list\" aria-label=\"開始からの時刻順の出来事\" aria-live=\"off\" tabindex=\"0\"></ol>\n        <div class=\"battle-log-history-navigation\"><button id=\"battleLogPrevious\" type=\"button\">前の120件</button><button id=\"battleLogLatest\" type=\"button\">最新へ</button><span id=\"battleLogRange\"></span></div>\n      </section>\n      <div id=\"reaction-backdrop\" class=\"reaction-backdrop\" hidden aria-hidden=\"true\"></div>\n    </section>\n\n    <section id=\"resultPanel\" class=\"result-panel\" hidden aria-live=\"polite\" aria-atomic=\"true\">\n      <p id=\"resultWinner\" class=\"result-winner\"></p>\n      <h3 id=\"message\" class=\"result-title\"></h3>\n      <span id=\"doubleUpBadge\" class=\"double-up-badge\" aria-hidden=\"true\" hidden>×2</span>\n      <span id=\"finalBlowCaption\" class=\"final-blow-caption\" aria-hidden=\"true\" hidden>決着</span>\n      <p id=\"breakdown\" class=\"result-summary\" aria-live=\"off\"></p>\n      <p id=\"battleInsights\" class=\"battle-insights\" hidden></p>\n      <button id=\"battleLogResult\" type=\"button\" hidden aria-expanded=\"false\" aria-controls=\"battleLogHistory\">戦闘ログ</button>\n      <p id=\"bankruptNotice\" class=\"bankrupt-notice\" hidden></p>\n      <p id=\"resultRanking\" class=\"result-ranking\" hidden></p>\n      <p id=\"checkpointNet\" class=\"checkpoint-net\" hidden></p>\n      <details id=\"multiResults\" class=\"multi-results\" open hidden>\n        <summary>参加者の結果</summary>\n        <div id=\"multiResultsList\" class=\"multi-results-list\"></div>\n      </details>\n      <div class=\"compatibility-hooks\" hidden aria-hidden=\"true\">\n        <span id=\"profit\"></span><span id=\"hits\"></span>\n      </div>\n      <button id=\"next\" class=\"cta cta-primary result-next\" type=\"button\" hidden>次の戦いへ</button>\n      <div id=\"extensionChoices\" class=\"extension-choices\" hidden><button id=\"cashOut\" type=\"button\">ここで終了</button><button id=\"continueRun\" type=\"button\">全額で続ける</button></div>\n      <p id=\"cashoutReceipt\" class=\"cashout-receipt\" aria-live=\"polite\" aria-atomic=\"true\" hidden></p>\n      <div id=\"resultProgress\" class=\"result-progress\" hidden aria-label=\"次の対戦まで\"><span id=\"resultProgressFill\"></span></div>\n      <p id=\"scoreStatus\" class=\"score-status\" aria-live=\"polite\"></p>\n      <button id=\"scoreRetry\" class=\"control-button\" type=\"button\" hidden>記録を再試行</button>\n    </section>\n    <div id=\"earnedFlightLayer\" class=\"earned-flight-layer\" aria-hidden=\"true\" hidden>\n      <span id=\"earnedBurst\" class=\"earned-burst\" hidden></span>\n            <span id=\"resultScatter0\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter1\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter2\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter3\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter4\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter5\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter6\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter7\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter8\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter9\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter10\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter11\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter12\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter13\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter14\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter15\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter16\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter17\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter18\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter19\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter20\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter21\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter22\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter23\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter24\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter25\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter26\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter27\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter28\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter29\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter30\" class=\"earned-coin result-scatter\"></span>\n      <span id=\"resultScatter31\" class=\"earned-coin result-scatter\"></span>\n    </div>\n  </section>\n\n  <section id=\"pausePanel\" class=\"units-panel pause-panel\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pauseTitle\" hidden>\n    <div class=\"units-dialog pause-dialog\">\n      <h2 id=\"pauseTitle\">一時停止</h2>\n      <p id=\"multiPauseNotice\" hidden>メニューを開いている間も対戦は進みます。</p>\n      <button id=\"pauseResume\" class=\"cta cta-primary\" type=\"button\">再開</button>\n      <button id=\"pauseExit\" class=\"text-button\" type=\"button\">終了</button>\n    </div>\n  </section>\n\n  <!-- The original has one UNITS action. This read-only overlay never changes the simulation. -->\n  <section id=\"unitsPanel\" class=\"units-panel\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"unitsTitle\" hidden>\n    <div class=\"units-dialog\">\n      <div class=\"units-heading\">\n        <h2 id=\"unitsTitle\">キャラ一覧</h2>\n        <button id=\"unitsClose\" class=\"text-button\" type=\"button\">閉じる</button>\n      </div>\n      <div class=\"units-grid\">\n        <section class=\"units-side units-side-red\" aria-labelledby=\"unitsRedTitle\">\n          <h3 id=\"unitsRedTitle\">左</h3>\n          <div id=\"unitsRedStats\" class=\"unit-stats units-stat-list comparison-list\" role=\"list\"></div>\n        </section>\n        <section class=\"units-side units-side-blue\" aria-labelledby=\"unitsBlueTitle\">\n          <h3 id=\"unitsBlueTitle\">右</h3>\n          <div id=\"unitsBlueStats\" class=\"unit-stats units-stat-list comparison-list\" role=\"list\"></div>\n        </section>\n      </div>\n      <p class=\"units-note\">ソロ: 停止 / オンライン: 続行</p>\n    </div>\n  </section>\n</main>\n\n\n";document.body.appendChild(t.content.cloneNode(true));})();
